var t=`0241-avgolemono-soup`;var o=`world-0241`;var n=`GR`;var a=`southern-europe`;var s=4;var r=44;var l={en:`Avgolemono Soup`,ua:`Суп авголемоно`};var m={en:`A traditional Greece dish made with chicken thigh, carrot, yellow onion, orzo pasta. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: куряче стегно, морква, жовта цибуля, паста орзо. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 24 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 24 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:24,i:[[`chicken-thigh`,500,`g`],[`water`,1300,`ml`],[`carrot`,120,`g`],[`yellow-onion`,120,`g`]]},{en:`Cook the listed ingredients in simmering water for about 12 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 12 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:12,i:[[`orzo-pasta`,160,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:4,i:[[`chicken-egg`,2,`pcs`],[`lemon-juice`,75,`ml`]]},{en:`Temper the egg-and-lemon mixture with hot broth, then stream it into the soup off the boil. Warm gently without boiling so the avgolemono remains smooth.`,ua:`Темперуйте яєчно-лимонну суміш гарячим бульйоном, тоді влийте в суп, знятий із кипіння. Обережно прогрійте без закипання, щоб авголемоно залишився гладким.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`dill`,12,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var h={slug:t,id:o,country:`GR`,region:a,servings:4,minutes:44,title:l,text:m,steps:g};export{n as country,h as default,o as id,r as minutes,a as region,s as servings,t as slug,g as steps,m as text,l as title};